if(!empty($_SESSION['parent_child_id'])){$s=$pdo->prepare('SELECT * FROM bayi_balita WHERE id=?');$s->execute([(int)$_SESSION['parent_child_id']]);$child=$s->fetch();if($child){$s=$pdo->prepare('SELECT service_date,weight,height,head_circumference FROM pelayanan_balita WHERE child_id=? ORDER BY service_date ASC');$s->execute([$child['id']]);$points=$s->fetchAll();}}
if(!empty($_SESSION['parent_mother_id'])){$s=$pdo->prepare('SELECT * FROM ibu_hamil WHERE id=?');$s->execute([(int)$_SESSION['parent_mother_id']]);$mother=$s->fetch();if($mother){$s=$pdo->prepare('SELECT * FROM pemeriksaan_ibu_hamil WHERE mother_id=? ORDER BY examination_date DESC LIMIT 10');$s->execute([$mother['id']]);$anc=$s->fetchAll();}}
