<?php if(count($points)>0): $maxW=max(15.0,max(array_map(fn($x)=>(float)($x['weight']??0),$points))+2);$minW=max(0.0,min(array_map(fn($x)=>(float)($x['weight']??0),$points))-2);$range=max(1,$maxW-$minW);$w=760;$h=300;$pl=55;$pr=20;$pt=20;$pb=50;$iw=$w-$pl-$pr;$ih=$h-$pt-$pb;$coords=[];foreach($points as $i=>$ptx){$x=$pl+($i/max(1,count($points)-1))*$iw;$y=$pt+(1-(((float)$ptx['weight']-$minW)/$range))*$ih;$coords[]=[$x,$y];}?>
<div class="chart-wrap"><svg viewBox="0 0 <?=$w?> <?=$h?>" class="growth-chart"><line x1="<?=$pl?>" y1="<?=$pt?>" x2="<?=$pl?>" y2="<?=$h-$pb?>" stroke="currentColor" opacity=".25"/><line x1="<?=$pl?>" y1="<?=$h-$pb?>" x2="<?=$w-$pr?>" y2="<?=$h-$pb?>" stroke="currentColor" opacity=".25"/><?php for($i=0;$i<=4;$i++):$v=$minW+$range*$i/4;$y=$pt+(1-$i/4)*$ih;?><line x1="<?=$pl?>" y1="<?=$y?>" x2="<?=$w-$pr?>" y2="<?=$y?>" stroke="currentColor" opacity=".08"/><text x="5" y="<?=$y+5?>" font-size="12"><?=number_format($v,1)?> kg</text><?php endfor;?><?php if(count($coords)>1):?><polyline points="<?=implode(' ',array_map(fn($c)=>$c[0].','.$c[1],$coords))?>" fill="none" stroke="currentColor" stroke-width="3"/><?php endif;?><?php foreach($coords as $i=>$c):?><circle cx="<?=$c[0]?>" cy="<?=$c[1]?>" r="5" fill="currentColor"/><text x="<?=$c[0]?>" y="<?=$h-15?>" text-anchor="middle" font-size="10"><?=htmlspecialchars(date('d/m',strtotime($points[$i]['service_date'])))?></text><?php endforeach;?></svg></div><?php else:?><p>Belum ada riwayat pertumbuhan.</p><?php endif;?></div><?php endif;?>
<?php if($mother):?><div class="panel-box"><h2>Riwayat Pemeriksaan Kehamilan</h2><div class="table-wrap"><table class="data-table"><tr><th>Tanggal</th><th>Usia Kehamilan</th><th>LILA</th><th>Tekanan Darah</th><th>Keluhan</th></tr><?php foreach($anc as $r):?><tr><td><?=htmlspecialchars($r['examination_date'])?></td><td><?=htmlspecialchars($r['gestational_age_weeks']??'-')?> minggu</td><td><?=htmlspecialchars($r['lila']??'-')?> cm</td><td><?=htmlspecialchars($r['blood_pressure']?:'-')?></td><td><?=htmlspecialchars($r['complaints']?:'-')?></td></tr><?php endforeach;?></table></div></div><?php endif;?>
<div class="panel-box" id="jadwal"><h2>Jadwal Posyandu Berikutnya</h2><?php if($jadwal):?><div class="table-wrap"><table class="data-table"><tr><th>Kegiatan</th><th>Tanggal</th><th>Jam</th><th>Lokasi</th></tr><?php foreach($jadwal as $j):?><tr><td><?=htmlspecialchars($j['title'])?></td><td><?=htmlspecialchars($j['event_date'])?></td><td><?=htmlspecialchars($j['event_time']?substr($j['event_time'],0,5):'-')?></td><td><?=htmlspecialchars($j['location']?:'-')?></td></tr><?php endforeach;?></table></div><?php else:?><p>Belum ada jadwal berikutnya.</p><?php endif;?></div>
<div class="panel-box" id="edukasi"><h2>Edukasi Kesehatan Dasar</h2><ul><li>Ikuti jadwal Posyandu dan pemeriksaan sesuai anjuran petugas.</li><li>Simpan catatan kesehatan dan hasil pemeriksaan untuk dibawa saat kunjungan.</li><li>Untuk keluhan atau kondisi yang mengkhawatirkan, hubungi tenaga kesehatan.</li></ul></div>
